config.script:
state = BlueRidge.Common.Util.extractQualifiedValues(self.view.custom.state) or {}
draft = dict(state.get("editDraft") or {})
baseline = state.get("selected") or {}
defId = draft.get("locationTypeDefinitionId")
if defId is None:
	draft["attributes"] = []
	self.view.custom.state = {"selected": baseline, "editDraft": draft}
	return
attrs = BlueRidge.Location.Location.buildAttributesForType(defId, None)
draft["attributes"] = attrs
self.view.custom.state = {"selected": baseline, "editDraft": draft}

customMethods.script:
# Abandonment path 3/3 -- the sort-order arrows commit straight to the DB,
# so an open draft would go stale and overwrite the new order on Save.
if self.view.custom.mode != "update":
	return
if not self.view.custom.dirty:
	self.applyMove(direction)
	return
self.view.custom.pendingNav = {"kind": "move", "direction": direction}
self.openUnsavedPrompt("You have unsaved changes to this Location. Save before reordering?")

pending = BlueRidge.Common.Util.extractQualifiedValues(self.view.custom.pendingNav) or {}
self.view.custom.pendingNav = None
if pending.get("kind") != "select":
	return
# Only the tree-selection gate moved the UI ahead of the decision; put the
# highlight back on the node whose draft we are keeping.
fromSelected = pending.get("fromSelected")
fromPath = pending.get("fromPath")
if fromSelected and fromSelected.get("id") is not None:
	self.view.custom.guardIgnoreId = fromSelected.get("id")
	self.view.custom.selected = fromSelected
if fromPath is not None:
	self.view.custom.selectedPath = fromPath
